    "/* check if word is a analyzable table folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAnalyzeIndex ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm checkIsWord not if EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  sTableNm checkIsTable not if popTable false exit then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable                                            // ../tables\n"
    "    assertInTables false exit\n"
    "  then\n"
    "\n"
    "  //pop indexes folder\n"
    "  popIndexes\n"
    "\n"
    "  // pop table folder\n"
    "  popTable\n"
    "\n"
    "  // assert in tables\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* anakyze index request (on originating node)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex_req ( -- <R> )\n"
    "\n"
    "  >>am <SEED_REQ>\n"
    "\n"
    "  0 0 0 locals| pJob pTask bIsDetailed |\n"
    "\n"
    "  tp: analyzeIndex\n"
    "\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  pJob jobAnalyzeIndex.isDetailed to bIsDetailed\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    bIsDetailed 1 == if\n"
    "      \\\"(nodeName VARCHAR, partition INTEGER, buffers INTEGER, bufferLevel VARCHAR, entries INTEGER)\\\"\n"
    "    else\n"
    "      \\\"(nodeName VARCHAR, partition INTEGER, buffers INTEGER, entries INTEGER)\\\"\n"
    "    then\n"
    "    pJob job.metadata!\n"
    "\n"
    "  then\n"
    "\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <<am <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_AnalyzeIndex job on a node                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex_exe ( Job_AnalyzeIndex -- )\n"
    "\n"
    "  >>am <SEED_EXE>\n"
    "\n"
    "  //params| pJob_AnalyzeIndex |\n"
    "  job::this locals| pJob_AnalyzeIndex |\n"
    "\n"
    "  0 0 locals| sTableNm bIsDetailed |\n"
    "\n"
    "  tp: analyzeIndex_exe\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // assert correct job\n"
    "  CN_JOB_ANALYZEINDEX pJob_AnalyzeIndex object.assertClass\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set task's dictionary stack from path in job\n"
    "  pJob_AnalyzeIndex job.pushPath\n"
    "  task::dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // push table\n"
    "  pJob_AnalyzeIndex job.objectName@ to sTableNm\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  //\n"
    "  // push indexes\n"
    "  pushIndexes assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // analyze the table\n"
    "  pJob_AnalyzeIndex jobAnalyzeIndex.isDetailed to bIsDetailed\n"
    "  bIsDetailed\n"
    "  pJob_AnalyzeIndex job.indexName@ find execute\n"
    "  index.analyze\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // put response in the job\n"
    "  grid::thisNode@ pJob_AnalyzeIndex job.response!\n"
    "  grid::slots grid::thisNode@ pJob_AnalyzeIndex job.rowsProcessed!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  popTable\n"
    "\n"
    "  pJob_AnalyzeIndex job.notice\n"
    "\n"
    "  pJob_AnalyzeIndex send_job__executed\n"
    "\n"
    "  <<am <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_AnalyzeIndex job check resources                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex.checkResources ( Job_AnalyzeIndex -- )\n"
    "\n"
    "  >>am <Check_Resources>\n"
    "\n"
    "  params| pJob_AnalyzeIndex  |\n"
    "\n"
    "  tp: analyzeIndex.checkResources\n"
    "  //\\\"checkResources received\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set task's dictionary stack from path in job\n"
    "  pJob_AnalyzeIndex job.pushPath\n"
    "  task::dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if we can remove the table\n"
    "  pJob_AnalyzeIndex job.objectName@\n"
    "  pJob_AnalyzeIndex job.indexName@\n"
    "  checkAnalyzeIndex not if pJob_AnalyzeIndex <ERROR_JOB> !!am exit then\n"
    "\n"
    "  <<am <Resources_Checked>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_AnalyzeIndex job release resources                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex.releaseResources ( Job_AnalyzeIndex -- )\n"
    "\n"
    "  >>am <Release_Resources>\n"
    "\n"
    "  params| pJob_AnalyzeIndex  |\n"
    "\n"
    "  tp: analyzeIndex.releaseResources\n"
    "  //\\\"releaseResources received\\\" .\n"
    "\n"
    "  <<am <Resources_Released>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex_beg ( -- )\n"
    "\n"
    "  >>am <SEED_BEG>\n"
    "\n"
    "  job::this locals| pJob_analyzeIndex |\n"
    "\n"
    "  pJob_analyzeIndex job.beginParticipant\n"
    "\n"
    "  // check resources\n"
    "  pJob_analyzeIndex analyzeIndex.checkResources\n"
    "\n"
    "  job::participantBegun\n"
    "\n"
    "  <<am <DONE_BEG>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex_end ( -- )\n"
    "\n"
    "  >>am <SEED_END>\n"
    "\n"
    "  job::this locals| pJob_analyzeIndex |\n"
    "\n"
    "  pJob_analyzeIndex analyzeIndex.releaseResources\n"
    "\n"
    "  job::participantEnded\n"
    "\n"
    "  <<am <DONE_END>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex_can ( -- )\n"
    "\n"
    "  >>am <SEED_CAN>\n"
    "\n"
    "  job::this locals| pJob_analyzeIndex |\n"
    "\n"
    "  pJob_analyzeIndex analyzeIndex.releaseResources\n"
    "\n"
    "  job::participantCancelled\n"
    "\n"
    "  <<am <DONE_CAN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_AnalyzeIndex.sen"_Stz
  ;

