  // munge of job_Lf.sen
  sDefinition =
    "\""
    "\\\"munged job_Lf.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Lf.sen -- Job list folder                                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Lf.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folders requests (on originating node)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lf_req ( -- <R> )\n"
    "\n"
    "  >>am <SEED_REQ>\n"
    "\n"
    "  0 0 0 locals| iCount pJob_Lf pTask |\n"
    "\n"
    "  tp: lf_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_Lf\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set task's dictionary stack from path in job\n"
    "  pJob_Lf job.pushPath\n"
    "  task::dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab ddl read lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR, type VARCHAR)\\\" pJob_Lf job.metadata!\n"
    "  then\n"
    "\n"
    "  \\\"\\\"\n"
    "  pathCurrentFolder dic.lastWord dup iterate\n"
    "  1 iCount + to iCount\n"
    "  \\\"row: ('\\\" str.cat\n"
    "\n"
    "  object@ word.name str.cat\n"
    "\n"
    "  \\\"', \\\" str.cat\n"
    "\n"
    "  object@ isTable if\n"
    "    \\\"'table'\\\" str.cat\n"
    "  then\n"
    "\n"
    "  object@ isIndex if\n"
    "    \\\"'index'\\\" str.cat\n"
    "  then\n"
    "\n"
    "  object@ isFolder if\n"
    "    \\\"'\\\" str.cat\n"
    "    object@ execute dic.kind@ word.name str.cat\n"
    "    \\\"'\\\" str.cat\n"
    "  then\n"
    "\n"
    "  iCount if\n"
    "    \\\")\\\\n\\\" str.cat\n"
    "  then\n"
    "\n"
    "  object@ word.prev object!\n"
    "\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in job\n"
    "  grid::thisNode@ pJob_Lf job.response!\n"
    "  iCount grid::thisNode@ pJob_Lf job.rowsProcessed!\n"
    "\n"
    "  <<am <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Lf.sen"_Stz
  ;

  vCompileConstant(sDefinition);

