  // munge of job_ListPartitions.sen
  sDefinition =
    "\""
    "\\\"munged job_ListPartitions.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_ListPartitions.sen -- Job list partitions                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_ListPartitions.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list partitions requests (on originating node)                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listPartitions_req ( -- <R> )\n"
    "\n"
    "  >>am <SEED_REQ>\n"
    "\n"
    "  0 0 locals| pJob_ListPartitions pTask |\n"
    "\n"
    "  tp: listPartitions_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_ListPartitions\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(NodeName VARCHAR, partitionNumber INTEGER)\\\"\n"
    "    pJob_ListPartitions job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob_ListPartitions job.distribute\n"
    "\n"
    "  <<am <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get space in the pool (executed on all nodes)                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listPartitions_exe ( pJob_ListPartitions -- )\n"
    "\n"
    "  >>am <SEED_EXE>\n"
    "\n"
    "  //params| pJob_Space |\n"
    "  job::this locals| pJob_ListPartitions |\n"
    "\n"
    "  CN_JOB_LISTPARTITIONS pJob_ListPartitions object.assertClass\n"
    "\n"
    "  \\\"\\\"   // intialize the string\n"
    "  grid::slots 0 do\n"
    "    I 0 != if \\\"\\\\n\\\" str.cat then\n"
    "    I grid::toPartition\n"
    "    I grid::toPartition grid::toNode grid::toNode grid::node node.name\n"
    "    \\\"row: ( %v, %v )\\\" str.format str.cat\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set response in job\n"
    "  grid::thisNode@ pJob_ListPartitions job.response!\n"
    "  grid::slots grid::thisNode@ pJob_ListPartitions job.rowsProcessed!\n"
    "\n"
    "  pJob_ListPartitions job.notice\n"
    "\n"
    "  pJob_ListPartitions send_job__executed\n"
    "\n"
    "  <<am <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listPartitions_beg ( -- )\n"
    "\n"
    "  >>am <SEED_BEG>\n"
    "\n"
    "  job::this locals| pJob_ListPartitions |\n"
    "\n"
    "  pJob_ListPartitions job.beginParticipant\n"
    "\n"
    "  job::participantBegun\n"
    "\n"
    "  <<am <DONE_BEG>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listPartitions_end ( -- )\n"
    "\n"
    "  >>am <SEED_END>\n"
    "\n"
    "  \\\">> listPartitions_end <<\\\" .verbose\n"
    "\n"
    "  job::participantEnded\n"
    "\n"
    "  <<am <DONE_END>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listPartitions_can ( -- )\n"
    "\n"
    "  >>am <SEED_CAN>\n"
    "\n"
    "  \\\">> listPartitions_can <<\\\" .verbose\n"
    "\n"
    "  job::participantCancelled\n"
    "\n"
    "  <<am <DONE_CAN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_ListPartitions.sen"_Stz
  ;

