  sDefinition =
    "\""
    "\\\"munged job_Pwf.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Pwf.sen -- Job Present Working Folder                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Pwf.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pwf command request                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pwf_req ( -- <R> )\n"
    "\n"
    "  >>am <SEED_REQ>\n"
    "  //\\\">>pwf_req\\\" activityMap::mark\n"
    "\n"
    "  100 apiState::senLoc\n"
    "\n"
    "  0 0 0 0 locals| pJob_Pwf pTask |\n"
    "\n"
    "  tp: cf_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_Pwf\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set task's dictionary stack from path in job\n"
    "  pJob_Pwf job.pushPath\n"
    "  task::dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(path VARCHAR)\\\" pJob_Pwf job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // start of working string\n"
    "  \\\"row: ('/\\\"\n"
    "\n"
    "  // iterate thru each folder in path and concat to end\n"
    "  pathDepth 0 do\n"
    "    // compute the path subscript\n"
    "    pathDepth 1 - I -\n"
    "    // pick the path, get its name and concat name to working string\n"
    "    pathPick dic.name str.cat\n"
    "    // concat \\\"/\\\" to end of working string\n"
    "    \\\"/\\\" str.cat\n"
    "  loop\n"
    "\n"
    "  // end working string\n"
    "  \\\"')\\\\n\\\" str.cat\n"
    "\n"
    "  grid::thisNode@ pJob_Pwf job.response!\n"
    "  1 grid::thisNode@ pJob_Pwf job.rowsProcessed!\n"
    "\n"
    "  900 apiState::senLoc\n"
    "\n"
    "  //\\\"<<pwf_req\\\" activityMap::mark\n"
    "    <<am <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Pwf.sen"_Stz
  ;

  vCompileConstant(sDefinition);

  // munge of job_Receiver.sen
  sDefinition =
    "\""
    "\\\"munged job_Receiver.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Receiver.sen -- receiver job                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Receiver.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn the receiver                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawn_Receiver ( pAnsweredNode iConnNo -- )\n"
    "\n"
    "  params| iConnNo |\n"
    "  params| pAnsweredNode |\n"
    "\n"
    "  0 locals| pJobClass_Receiver |\n"
    "  0 locals| pJob_Receiver |\n"
    "\n"
    "  CN_JOB_RECEIVER jobClass::find to pJobClass_Receiver\n"
    "\n"
    "  nullptr pJobClass_Receiver jobClass.new to pJob_Receiver\n"
    "\n"
    "  iConnNo       pJob_Receiver job_receiver.connNo!\n"
    "  pAnsweredNode pJob_Receiver job_receiver.node!\n"
    "\n"
    "  pJob_Receiver SEED_RUN job.spawn\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* receiver init                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": receiver_init ( -- )\n"
    "\n"
    "  CN_JOB_RECEIVER task::this task.thread thread.dedicated!\n"
    "\n"
    "  args.verbose if\n"
    "    grid::thisNode@ \\\"receiver running on node %v\\\" fmt.print\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* receiver loop: receive a job, execute it                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": receiver_loop ( -- )\n"
    "\n"
    "  0 locals| pReceivedJob |\n"
    "  0 locals| pEntryBuffer |\n"
    "  0 locals| pOtherNode |\n"
    "  0 locals| pSocket |\n"
    "\n"
    "  job::this locals| pJob_Receiver |\n"
    "\n"
    "  pJob_Receiver job_Receiver.node@ to pOtherNode\n"
    "\n"
    "  pOtherNode node.recvSocket@ to pSocket\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  begin\n"
    "\n"
    "    assertStackDepthZero\n"
    "\n"
    "    pSocket socket.recvObject drop to pReceivedJob\n"
    "\n"
    "    pReceivedJob not if\n"
    "      ifAgain\n"
    "    then\n"
    "\n"
    "    pReceivedJob job.postRecv\n"
    "\n"
    "    pReceivedJob job.hasEntryBuffer if\n"
    "      pSocket socket.recvObject drop to pEntryBuffer\n"
    "      pEntryBuffer pReceivedJob job.entryBuffer!\n"
    "    then\n"
    "\n"
    "    pReceivedJob SEED_RCV job.spawn\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* receiver seed                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": receiver_run ( -- )\n"
    "\n"
    "  >>am <SEED_RUN>\n"
    "\n"
    "  // initialise\n"
    "  receiver_init\n"
    "\n"
    "  // loop, receiving and executing jobs\n"
    "  receiver_loop\n"
    "\n"
    "  // should never exit\n"
    "  hazard\n"
    "\n"
    "  <DONE_RUN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Receiver.sen"_Stz
  ;

  vCompileConstant(sDefinition);

