  // munge of job_Sanity.sen
  sDefinition =
    "\""
    "\\\"munged job_Sanity.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Sanity.sen -- Job Sanity                                               */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Sanity.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* request to get sanity of nodes in the grid (on originating node)           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_req ( -- <R> )\n"
    "\n"
    "  >>am <SEED_REQ>\n"
    "\n"
    "  0 0 locals| pJob pTask |\n"
    "\n"
    "  tp: sanity_req\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set metadata string in the job\n"
    "  args.metadata if\n"
    "    \\\"(nodeName VARCHAR, sanity VARCHAR)\\\"\n"
    "  pJob job.metadata!\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // distribute the job\n"
    "  pJob job.distribute\n"
    "\n"
    "  <<am <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_Sanity job                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_exe ( pJob_Sanity -- )\n"
    "\n"
    "  >>am <SEED_EXE>\n"
    "\n"
    "  //params| pJob_Sanity |\n"
    "  job::this locals| pJob_Sanity |\n"
    "\n"
    "  0 0 locals| iSize iPartitions |\n"
    "\n"
    "  CN_JOB_SANITY pJob_Sanity object.assertClass\n"
    "\n"
    "  //\\\"GETTING SANITY on NODE \\\" grid::thisNode@ >str str.cat .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the node size of originating node from the job\n"
    "  pJob_Sanity job.regionSize@ to iSize\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the no of partitions of originating node from the job\n"
    "  pJob_Sanity job.partitions@ to iPartitions\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  args.tracepoint if\n"
    "    \\\"GETTING PARTITIONS on NODE \\\" grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  iPartitions node.partitions == not if\n"
    "    EC_CLUSTER_PARTITIONS_MISMATCH\n"
    "    grid::thisNode@ pJob_Sanity job.error!\n"
    "  else\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    args.tracepoint if\n"
    "      \\\"GETTING SIZE on NODE \\\"grid::thisNode@ >str str.cat .\n"
    "    then\n"
    "\n"
    "    iSize node.size == not if\n"
    "      EC_CLUSTER_SIZE_MISMATCH\n"
    "      grid::thisNode@ pJob_Sanity job.error!\n"
    "    else\n"
    "      \\\"row: ('\\\"\n"
    "      grid::thisNodeName@ str.cat\n"
    "       \\\"','sanity check passed')\\\" str.cat\n"
    "      grid::thisNode@ pJob_Sanity job.response!\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  pJob_Sanity job.notice\n"
    "\n"
    "  pJob_Sanity send_job__executed\n"
    "\n"
    "  <<am <DONE_EXE>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity__beg ( -- )\n"
    "\n"
    "  >>am <SEED_BEG>\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  pJob_sanity job.beginParticipant\n"
    "\n"
    "  job::participantBegun\n"
    "\n"
    "  <<am <DONE_BEG>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_end ( -- )\n"
    "\n"
    "  >>am <SEED_END>\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  job::participantEnded\n"
    "\n"
    "  <<am <DONE_END>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sanity_can ( -- )\n"
    "\n"
    "  >>am <SEED_CAN>\n"
    "\n"
    "  job::this locals| pJob_sanity |\n"
    "\n"
    "  job::participantCancelled\n"
    "\n"
    "  <<am <DONE_CAN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT job_Sanity.sen"_Stz
  ;

