  // munge of job_SelectTable.sen
  sDefinition =
    "\""
    "\\\"munged job_SelectTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_SelectTable.sen -- Job Select Table                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_SelectTable.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* select table request (on originating node)                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": selectTable_req ( -- <R> )\n"
    "\n"
    "  >>am <SEED_REQ>\n"
    "\n"
    "  100 apiState::senLoc\n"
    "\n"
    "  0 0 locals| sTableNm  iPartition |\n"
    "  0 0 0 locals| pJob_SelectTable pTask pTable |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the task\n"
    "  task::this to pTask\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the job from the task\n"
    "  pTask task.job@ to pJob_SelectTable\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // assert correct job\n"
    "  CN_JOB_SELECTTABLE pJob_SelectTable object.assertClass\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set task's dictionary stack from path in job\n"
    "  pJob_SelectTable job.pushPath\n"
    "  task::dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the table name\n"
    "  pJob_SelectTable job.objectName@ to sTableNm\n"
    "\n"
    "  pJob_SelectTable job_selectTable.partition@ to iPartition\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  //check if we can fetch rows from selected table\n"
    "  sTableNm iPartition checkFetchRows not if pJob_SelectTable <ERROR_REQUEST> !!am exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // find the table\n"
    "  sTableNm pushTable assert\n"
    "  sTableNm find execute to pTable\n"
    "  pTable pJob_SelectTable job_selectTable.table!\n"
    "\n"
    "  popTable\n"
    "\n"
    "  pJob_SelectTable job.notice\n"
    "\n"
    "  900 apiState::senLoc\n"
    "\n"
    "  <<am <DONE_REQ>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_SelectTable.sen"_Stz
  ;

