    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set task's dictionary stack from path in job\n"
    "  pJob_TableSizes job.pushPath\n"
    "  task::dicStack.set\n"
    "\n"
    "  //\\\"hidden\\\" find execute to pIndex\n"
    "  //pIndex index.space 0 swap number.magnitude to iSize\n"
    "  //iSize grid::thisNodeName@ \\\"row: ( %v %v )\\\" str.format\n"
    "\n"
    "  //\\\"STACK IS a:\\\" . stk\n"
    "\n"
    "  //\\\"\\\"\n"
    "  pathCurrentFolder dic.lastWord dup\n"
    "  iterate\n"
    "    1 iCount + to iCount\n"
    "    grid::thisNodeName@ \\\"row: ('%v', '\\\" str.format\n"
    "\n"
    "    object@ word.name to sTableNm\n"
    "    sTableNm str.cat\n"
    "\n"
    "    \\\"', '\\\" str.cat\n"
    "\n"
    "    // push table dictionary\n"
    "    sTableNm pushTable assert\n"
    "\n"
    "    // check it is a table\n"
    "    sTableNm checkIsTable not if drop pJob_TableSizes <ERROR_JOB> !!am exit then\n"
    "\n"
    "    // push indexes folder\n"
    "    pushIndexes assert\n"
    "\n"
    "    //get size of hidden index\n"
    "    \\\"hidden\\\" find execute index.space 0 swap number.magnitude to iSize\n"
    "    iSize >str\n"
    "    str.cat\n"
    "\n"
    "    // pop indexes folder\n"
    "    popIndexes\n"
    "\n"
    "    // pop table folder\n"
    "    popTable\n"
    "\n"
    "    \\\"')\\\\n\\\" str.cat\n"
    "\n"
    "    object@ word.prev object!\n"
    "\n"
    "  next\n"
    "\n"
    "  //\\\"STACK IS b:\\\" . stk\n"
    "\n"
    "  grid::thisNode@ pJob_TableSizes job.response!\n"
    "  iCount grid::thisNode@ pJob_TableSizes job.rowsProcessed!\n"
    "\n"
    "  pJob_TableSizes job.notice\n"
    "\n"
    "  pJob_TableSizes send_job__executed\n"
    "\n"
    "  <<am <DONE_EXE>\n"
    "\n"
    "  //\\\"STACK IS c:\\\" . stk\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SizeTable job check resources                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableSizes.checkResources ( Job_TableSizes -- )\n"
    "\n"
    "  >>am <Check_Resources>\n"
    "\n"
    "  params| pJob_TableSizes  |\n"
    "\n"
    "  tp: tableSizes.checkResources\n"
    "  //checkResources received\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set task's dictionary stack from path in job\n"
    "  pJob_TableSizes job.pushPath\n"
    "  task::dicStack.set\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if pJob_TableSizes <ERROR_JOB> !!am exit then\n"
    "\n"
    "  <<am <Resources_Checked>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_SizeTable job release resources                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableSizes.releaseResources ( Job_SizeTable -- )\n"
    "\n"
    "  >>am <Release_Resources>\n"
    "\n"
    "  params| pJob_SizeTable  |\n"
    "\n"
    "  tp: sizeTable.releaseResources\n"
    "  //releaseResources received\\\" .\n"
    "\n"
    "  <<am <Resources_Released>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableSizes_beg ( -- )\n"
    "\n"
    "  >>am <SEED_BEG>\n"
    "\n"
    "  job::this locals| pJob_tableSizes |\n"
    "\n"
    "  pJob_tableSizes job.beginParticipant\n"
    "\n"
    "  // check resources\n"
    "  pJob_tableSizes tableSizes.checkResources\n"
    "\n"
    "  job::participantBegun\n"
    "\n"
    "  <<am <DONE_BEG>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job                                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableSizes_end ( -- )\n"
    "\n"
    "  >>am <SEED_END>\n"
    "\n"
    "  job::this locals| pJob_tableSizes |\n"
    "\n"
    "  pJob_tableSizes tableSizes.releaseResources\n"
    "\n"
    "  job::participantEnded\n"
    "\n"
    "  <<am <DONE_END>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableSizes_can ( -- )\n"
    "\n"
    "  >>am <SEED_CAN>\n"
    "\n"
    "  job::this locals| pJob_tableSizes |\n"
    "\n"
    "  pJob_tableSizes tableSizes.releaseResources\n"
    "\n"
    "  job::participantCancelled\n"
    "\n"
    "  <<am <DONE_CAN>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_TableSizes.sen"_Stz
  ;

  vCompileConstant(sDefinition);

