    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop all values on stack except topmost                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": nipAll ( ... top -- top )\n"
    "\n"
    "  // handle expty stack case\n"
    "  depth not if exit then\n"
    "\n"
    "  // save topmost\n"
    "  >r\n"
    "\n"
    "  // drop everything else\n"
    "  begin\n"
    "    depth while\n"
    "      drop\n"
    "  repeat\n"
    "\n"
    "  // restore topmost\n"
    "  r>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop n values from stack                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropN ( ... #values -- )\n"
    "\n"
    "  // handle expty stack case\n"
    "  depth not if exit then\n"
    "\n"
    "  // drop everything else\n"
    "  0 do\n"
    "    drop\n"
    "  loop\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT wordSet_corePlus.sen"_Stz
  ;

